module TopModule (
    input clk,
    input L,
    input q_in,
    input r_in,
    output reg Q
);

    // 2:1 multiplexer followed by a D flip-flop.
    // L = 1: load from r_in
    // L = 0: hold the feedback value q_in (computed by the parent module)
    always @(posedge clk) begin
        if (L)
            Q <= r_in;
        else
            Q <= q_in;
    end

endmodule
```

This submodule contains the 2:1 mux (select between `r_in` and `q_in` using `L`) plus one D flip-flop. Instantiating it three times in `full_module` reproduces the original behavior, with the parent wiring each instance's `q_in` to the appropriate feedback term: `{q[1]^q[2]}` for bit 2, `q[0]` for bit 1, and `q[2]` for bit 0.
